<?php if(empty($startupDetailsOnly))$startupPreview=vs_startup_preflight($configuration,!empty($_POST['tool_terms'])); ?>
<section class="startup-preflight" data-startup-preflight aria-label="Work availability">
<?php if(empty($startupDetailsOnly)): ?><p role="status"><strong><?=e(!empty($startupSummaryOnly)&&!$startupPreview['eligible']&&$startupPreview['reasons']?$startupPreview['reasons'][0]['message']:$startupPreview['summary'])?></strong></p>
<?php if(empty($startupSummaryOnly)&&$startupPreview['reasons']&&!$startupPreview['eligible']): ?><p class="fine"><?=e($startupPreview['reasons'][0]['message'])?></p><?php endif ?>
<?php endif ?>
<?php if(empty($startupSummaryOnly)): ?><details id="startup-settings" class="research-disclosure" <?=!empty($_POST['startup_edit'])&&!$startupPreview['eligible']?'open':''?>><summary><?=!empty($startupEditable)?'Capabilities & availability':'Why work may be unavailable'?></summary>
<?php foreach($startupPreview['reasons'] as $reason): ?><p><strong><?=e($reason['message'])?></strong> <?=e($reason['action'])?></p><?php if(isset($reason['earliest_expiry'])): ?><p>Earliest matching reservation expiry: <?=e($reason['earliest_expiry'])?> UTC. Availability is rechecked at pickup.</p><?php endif ?><?php foreach($reason['examples'] as $blocked): ?><p><a href="<?=e($blocked['url'])?>"><?=e($blocked['title'])?></a> · <?=e($blocked['requirements'])?></p><?php endforeach ?><?php endforeach ?>
<?php foreach($startupPreview['examples'] as $example): ?><p><a href="<?=e($example['url'])?>"><?=e($example['title'])?></a> · <?=e($example['kind'])?></p><?php endforeach ?>
<p class="fine">A preview reserves no work. Pickup checks the current task, capabilities, consent and reservation.</p>
<?php if(!empty($startupEditable)): ?>
<form method="post" action="/volunteer"><?=csrf()?><input type="hidden" name="operation" value="configure"><input type="hidden" name="startup_edit" value="1"><input type="hidden" name="setup_version" value="3">
<?php foreach($draft as $name=>$value): if(in_array($name,['setup_version','session_profile','model','reasoning','tool','workflow_mode'],true))continue; ?><input type="hidden" name="<?=e($name)?>" value="<?=e($value)?>"><?php endforeach ?>
<label for="startup-capabilities">AI capabilities</label><select id="startup-capabilities" name="session_profile"><?php foreach(VS_PROFILES as $id=>$profile): ?><option value="<?=e($id)?>" <?=vs_profile_id($configuration)===$id?'selected':''?>><?=e($profile['label'])?></option><?php endforeach ?></select>
<div class="actions"><button>Recheck availability</button><a class="button secondary" href="/volunteer">Change scope or limits</a></div></form>
<?php elseif(isset($configuration['id'])&&!vs_current($configuration)): ?><form method="post" action="/volunteer"><?=csrf()?><?php foreach(vs_startup_restart_input($configuration) as $name=>$value): ?><input type="hidden" name="<?=e($name)?>" value="<?=e($value)?>"><?php endforeach ?><button class="secondary">Review settings for a new session</button></form><p class="fine">Scope, capabilities and limits are carried forward for your review. Existing session settings and consent remain unchanged.</p><?php endif ?>
</details><?php endif ?></section>
